{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "IAM policy allows wildcard (*) resource",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "HIGH",
      "explanation": "The IAM policy allows actions on all resources ('*'), which can lead to privilege escalation or unintended access. Restricting the resource to specific ARNs reduces the risk of abuse."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-sageMakerCreatePresignedNotebookURL-policy" {
  name        = "privesc-sageMakerCreatePresignedNotebookURL-policy"
  path        = "/"
  description = "Allows privesc via sagemakerCreatePresignedNotebookURL"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "sagemaker:CreatePresignedNotebookInstanceUrl",
          "sagemaker:ListNotebookInstances"
        ]
        Resource = [
          "arn:aws:sagemaker:REGION:ACCOUNT_ID:notebook-instance/NOTEBOOK_INSTANCE_NAME"
        ]
      },
    ]
  })
}",
  "fix_summary": "Restricted the IAM policy's 'Resource' field to a specific ARN for the SageMaker notebook instance, replacing the wildcard (*) to minimize the risk of privilege escalation or unintended access."
}
